function Earnings({ go }: { go: (s: ScreenName) => void }) { const s = useStyles(); const [tab, setTab] = useState("This Week"); const bars = [52, 80, 45, 94, 68, 76, 58]; return <ScrollView contentContainerStyle={s.content}><Header title="Earnings" subtitle="Track your income and payouts" /><View style={s.rowWrap}>{["Today", "This Week", "This Month", "All"].map((x) => <Pressable key={x} onPress={() => setTab(x)} style={[s.chip, tab === x && s.chipSelected]}><Text style={[s.chipText, tab === x && s.chipSelectedText]}>{x}</Text></Pressable>)}</View><Card style={{ marginTop: 12, backgroundColor: "#0B1F3A", borderColor: "#0B1F3A", gap: 6 }}><Text style={{ color: "#A9D6FF", fontSize: 11, fontWeight: "800" }}>TOTAL EARNINGS · {tab.toUpperCase()}</Text><Text style={{ color: "#FFFFFF", fontSize: 30, fontWeight: "800" }}>₹12,450</Text><Text style={{ color: "#A9D6FF", fontSize: 12 }}>+12.5% from last week</Text></Card><View style={[s.row, { gap: 8, marginTop: 12 }]}><StatCard label="Completed jobs" value="8" icon="checkmark-circle-outline" accent="#15966D" /><StatCard label="Pending" value="₹2,400" icon="time-outline" accent="#C8871A" /><StatCard label="Paid" value="₹10,050" icon="wallet-outline" accent="#0B63CE" /></View><SectionTitle title="Earnings overview" /><Card><View style={s.chart}>{bars.map((height, i) => <View key={i} style={{ alignItems: "center" }}><View style={[s.bar, { height }]} /><Text style={s.chartLabel}>{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"][i]}</Text></View>)}</View></Card><SectionTitle title="Recent payouts" action="View all" onAction={() => go("history")} /><Card>{[{ date: "12 Sep 2026", amount: "₹1,500", status: "Completed" }, { date: "10 Sep 2026", amount: "₹2,300", status: "Completed" }, { date: "08 Sep 2026", amount: "₹1,800", status: "Completed" }].map((p) => <View key={p.date} style={[s.between, s.listRow]}><View><Text style={s.h3}>{p.amount}</Text><Text style={s.muted}>{p.date}</Text></View><Badge text={p.status} tone="success" /></View>)}</Card></ScrollView>; }

function Notifications({ go, state, update }: { go: (s: ScreenName) => void; state: AppState; update: (p: Partial<AppState>) => void }) { const s = useStyles(); return <ScrollView contentContainerStyle={s.content}><Header title="Notifications" subtitle="Stay on top of your work" /><View style={s.gap8}>{state.notifications.map((n) => <Pressable key={n.id} onPress={() => update({ notifications: state.notifications.map((x) => x.id === n.id ? { ...x, unread: false } : x) })}><Card style={[s.row, { gap: 12, borderColor: n.unread ? "#9EC7EE" : "#DCE5EF" }]}><View style={[s.avatar, { width: 40, height: 40, borderRadius: 20, backgroundColor: n.kind === "payment" ? "#E7F7F0" : "#EAF4FF" }]}><Icon name={n.kind === "payment" ? "wallet" : n.kind === "message" ? "chatbubble" : "briefcase"} color={n.kind === "payment" ? "#15966D" : "#0B63CE"} size={18} /></View><View style={{ flex: 1, gap: 3 }}><View style={s.between}><Text style={s.h3}>{n.title}</Text>{n.unread ? <View style={{ width: 7, height: 7, borderRadius: 4, backgroundColor: "#0B63CE" }} /> : null}</View><Text style={s.body}>{n.text}</Text><Text style={s.tiny}>{n.time}</Text></View></Card></Pressable>)}</View><Button title="Mark all as read" secondary onPress={() => update({ notifications: state.notifications.map((x) => ({ ...x, unread: false })) })} /></ScrollView>; }

function Profile({ go, state }: { go: (s: ScreenName) => void; state: AppState }) { const s = useStyles(); const items: [string, IconName, ScreenName][] = [["Personal Information", "person-outline", "details"], ["Skills & Trades", "construct-outline", "details"], ["Service Area", "map-outline", "area"], ["Availability", "calendar-outline", "area"], ["Ratings & Reviews", "star-outline", "history"], ["Bank Details", "card-outline", "earnings"]]; return <ScrollView contentContainerStyle={s.content}><Header title="Profile" subtitle="Your professional identity" onBell={() => go("notifications")} /><Card style={{ alignItems: "center", gap: 8 }}><View style={[s.avatar, { width: 78, height: 78, borderRadius: 39 }]}><Text style={{ color: "#0B63CE", fontSize: 26, fontWeight: "800" }}>VP</Text></View><Text style={s.h2}>{state.worker.name}</Text><Text style={s.muted}>{state.worker.trade}</Text><View style={s.row}><Icon name="star" color="#E5A523" /><Text style={[s.h3, { marginLeft: 5 }]}>4.8</Text><Text style={s.muted}> · 126 completed jobs</Text></View><Button title="Edit Profile" secondary onPress={() => go("details")} /></Card><View style={[s.row, { gap: 8, marginTop: 12 }]}><StatCard label="Rating" value="4.8" icon="star" accent="#E5A523" /><StatCard label="Jobs done" value="126" icon="checkmark-done" accent="#15966D" /><StatCard label="Earnings" value="₹48K" icon="wallet" accent="#0B63CE" /></View><Card style={{ marginTop: 18, paddingVertical: 5 }}>{items.map(([label, icon, screen]) => <Pressable key={label} onPress={() => go(screen)} style={[s.between, { minHeight: 54, borderBottomWidth: 1, borderBottomColor: "#E5EDF5" }]}><View style={s.row}><Icon name={icon} color="#58708C" /><Text style={[s.body, { marginLeft: 12 }]}>{label}</Text></View><Icon name="chevron-forward" color="#8AA0B5" size={17} /></Pressable>)}</Card><Button title="Settings" secondary icon="settings-outline" onPress={() => go("settings")} /></ScrollView>; }

function Settings({ go, signOut }: { go: (s: ScreenName) => void; signOut: () => void }) { const s = useStyles(); const [push, setPush] = useState(true); const [location, setLocation] = useState(true); return <ScrollView contentContainerStyle={s.content}><Header title="Settings" onBack={() => go("profile")} /><Card style={{ paddingVertical: 5 }}>{[["Notifications", "Receive job and payment updates", push, setPush, "notifications-outline"], ["Location access", "Show jobs within your service area", location, setLocation, "location-outline"]].map(([title, sub, value, setter, icon]) => <View key={title as string} style={[s.between, { minHeight: 68, borderBottomWidth: 1, borderBottomColor: "#E5EDF5" }]}><View style={s.row}><Icon name={icon as IconName} /><View style={{ marginLeft: 12 }}><Text style={s.h3}>{title as string}</Text><Text style={s.tiny}>{sub as string}</Text></View></View><Switch value={value as boolean} onValueChange={setter as any} trackColor={{ false: "#C9D5E0", true: "#7FB4E9" }} thumbColor={value ? "#0B63CE" : "#FFFFFF"} /></View>)}{[["Language", "English", "language-outline"], ["Privacy & Security", "Control your account security", "lock-closed-outline"], ["Help & Support", "FAQs, chat and tickets", "help-circle-outline"], ["Terms & Conditions", "Worker platform terms", "document-text-outline"]].map(([title, sub, icon]) => <Pressable key={title} onPress={() => title === "Help & Support" && go("support")} style={[s.between, { minHeight: 60, borderBottomWidth: 1, borderBottomColor: "#E5EDF5" }]}><View style={s.row}><Icon name={icon as IconName} /><View style={{ marginLeft: 12 }}><Text style={s.h3}>{title}</Text><Text style={s.tiny}>{sub}</Text></View></View><Icon name="chevron-forward" color="#8AA0B5" size={17} /></Pressable>)}</Card><View style={{ marginTop: 20 }}><Button title="Log out" secondary icon="log-out-outline" onPress={() => Alert.alert("Log out?", "You can sign in again anytime.", [{ text: "Cancel" }, { text: "Log out", onPress: signOut }])} /></View><Text style={[s.tiny, { textAlign: "center", marginTop: 28 }]}>ShedX Worker Portal · v1.0.0</Text></ScrollView>; }

function Support({ go }: { go: (s: ScreenName) => void }) { const s = useStyles(); const [modal, setModal] = useState(false); const [ticket, setTicket] = useState(""); const [description, setDescription] = useState(""); const faqs = ["How do I accept a new job?", "When are payouts processed?", "How do I update my service area?"]; return <ScrollView contentContainerStyle={s.content}><Header title="Help & support" subtitle="We are here to keep you moving" onBack={() => go("profile")} /><Card style={{ backgroundColor: "#0B1F3A", borderColor: "#0B1F3A", gap: 8 }}><Text style={{ color: "#A9D6FF", fontSize: 11, fontWeight: "800" }}>SUPPORT HOURS</Text><Text style={{ color: "#FFFFFF", fontSize: 22, fontWeight: "800" }}>Need immediate help?</Text><Text style={{ color: "#C5D7EA", fontSize: 13 }}>Our team is online today from 9 AM – 9 PM.</Text><Button title="Call Support" secondary icon="call-outline" onPress={() => Alert.alert("Support", "Calling +91 98765 43210")} /></Card><SectionTitle title="FAQs" /><Card>{faqs.map((x) => <Pressable key={x} onPress={() => Alert.alert(x, "Our support team can guide you through this in the worker app.")} style={[s.between, { minHeight: 52, borderBottomWidth: 1, borderBottomColor: "#E5EDF5" }]}><Text style={s.body}>{x}</Text><Icon name="chevron-forward" color="#8AA0B5" size={17} /></Pressable>)}</Card><SectionTitle title="Contact support" /><View style={[s.row, s.gap8]}><Button title="Live Chat" secondary icon="chatbubble-outline" onPress={() => Alert.alert("Live chat", "A support specialist will join shortly.")} /><Button title="Raise an issue" icon="add" onPress={() => setModal(true)} /></View><SectionTitle title="Existing tickets" /><Card>{ticket ? <View style={s.between}><View><Text style={s.h3}>{ticket}</Text><Text style={s.muted}>Work order support request</Text></View><Badge text="Open" tone="warning" /></View> : <Text style={s.muted}>No open support tickets.</Text>}</Card><ModalSheet visible={modal} title="Raise an issue" onClose={() => setModal(false)}><View style={s.gap16}><Field label="Job" value="Roof Panel Repair · ABC Manufacturing" /><Field label="Category" value="Site access" /><Field label="Priority" value="Normal" /><Field label="Description" value={description} onChangeText={setDescription} multiline placeholder="Tell us what happened" /><Button title="Submit issue" onPress={async () => { const id = await supportService.createTicket(); setTicket(id); setDescription(""); setModal(false); }} /></View></ModalSheet></ScrollView>; }

function AppShell({ screen, go, state, update, signOut, children }: { screen: ScreenName; go: (s: ScreenName) => void; state: AppState; update: (p: Partial<AppState>) => void; signOut: () => void; children: React.ReactNode }) { const s = useStyles(); const { width } = useWindowDimensions(); const insets = useSafeAreaInsets(); const showChrome = !["welcome", "login", "register", "details", "area", "success", "ready", "accepted", "navigation", "arrived", "start", "job", "materials", "progress", "photos", "confirmation", "completed"].includes(screen); const items: [string, IconName, ScreenName][] = [["Home", "home-outline", "home"], ["Jobs", "briefcase-outline", "jobs"], ["Work", "construct-outline", "work"], ["Earnings", "wallet-outline", "earnings"], ["Profile", "person-outline", "profile"]]; if (!showChrome) return <View style={[s.root, { paddingTop: insets.top }]}>{children}</View>; const desktop = width >= 760; return <View style={s.root}>{desktop ? <View style={{ flex: 1, flexDirection: "row" }}><View style={s.sidebar}><Logo /><Text style={s.tiny}>WORKER PORTAL</Text><View style={{ height: 8 }} />{items.map(([label, icon, target]) => <Pressable key={label} accessibilityRole="button" accessibilityLabel={label} onPress={() => go(target)} style={[s.sideItem, screen === target && s.sideItemActive]}><Icon name={icon} color={screen === target ? "#0B63CE" : undefined} /><Text style={[s.sideText, screen === target && s.sideTextActive]}>{label}</Text></Pressable>)}<View style={{ flex: 1 }} /><Pressable accessibilityRole="button" accessibilityLabel="Notifications" onPress={() => go("notifications")} style={s.sideItem}><Icon name="notifications-outline" /><Text style={s.sideText}>Notifications</Text></Pressable><Pressable accessibilityRole="button" accessibilityLabel="Settings" onPress={() => go("settings")} style={s.sideItem}><Icon name="settings-outline" /><Text style={s.sideText}>Settings</Text></Pressable></View><View style={s.page}>{children}</View></View> : <View style={s.page}>{children}<View style={[s.bottomNav, { paddingBottom: Math.max(insets.bottom, 8) }]}>{items.map(([label, icon, target]) => <Pressable key={label} accessibilityRole="button" accessibilityLabel={label} onPress={() => go(target)} style={s.navItem}><Icon name={icon} color={screen === target ? "#0B63CE" : undefined} /><Text style={[s.navText, screen === target && s.navActive]}>{label}</Text></Pressable>)}</View></View>}</View>; }

export default function Index() {
  const s = useStyles(); const [screen, setScreen] = useState<ScreenName>("welcome"); const [state, setState] = useState<AppState>(initialAppState); const [loading, setLoading] = useState(true); const [toast, setToast] = useState("");
  useEffect(() => { storageService.load().then((saved) => { setState(saved); setLoading(false); }); }, []);
  useEffect(() => { if (!loading) storageService.save(state); }, [state, loading]);
  useEffect(() => { if (!state.authenticated) return; let cancelled = false; (async () => { try { const [profile, status, requestFeed, noteFeed] = await Promise.all([remoteWorkerService.profile(), remoteWorkerService.status(), remoteJobService.requests(), remoteNotificationService.list()]); if (cancelled) return; const worker = profile as any; replaceJobs((requestFeed as any[]).map(normalizeJob)); update({ worker: { ...state.worker, name: worker.full_name ?? state.worker.name, trade: worker.primary_trade ?? state.worker.trade, rating: Number(worker.rating_avg ?? state.worker.rating), jobs: Number(worker.completed_jobs_count ?? state.worker.jobs) }, isOnline: (status as any)?.availability_status === "ONLINE", notifications: (noteFeed as any[]).map((n) => ({ id: String(n.id), kind: String(n.type ?? "system").toLowerCase(), title: n.title, text: n.message, time: n.created_at ?? "", unread: !n.is_read })), selectedJobId: (requestFeed as any[])[0]?.id ?? state.selectedJobId }); } catch { if (!cancelled) setToast("Backend unavailable — saved workspace is active"); } })(); return () => { cancelled = true; }; }, [state.authenticated]);
  const go = (next: ScreenName) => { const id = state.selectedJobId; const actions: Partial<Record<ScreenName, (jobId: string) => Promise<unknown>>> = { accepted: remoteJobService.accept, navigation: remoteJobService.enRoute, arrived: remoteJobService.arrived, work: remoteJobService.start, completed: remoteJobService.complete }; if (actions[next]) actions[next]?.(id).catch(() => setToast("Backend transition unavailable — showing local state")); setScreen(next); setToast(""); };
  const update = (patch: Partial<AppState>) => { setState((p) => ({ ...p, ...patch })); if (patch.isOnline !== undefined) remoteWorkerService.updateStatus(patch.isOnline ? "ONLINE" : "OFFLINE").catch(() => setToast("Could not sync worker availability")); if (patch.progress !== undefined || patch.currentTask !== undefined) remoteJobService.saveProgress(state.selectedJobId, { progress_percent: patch.progress ?? state.progress, status: "IN_PROGRESS", current_task: patch.currentTask ?? state.currentTask }).catch(() => setToast("Could not sync work progress")); setToast("Saved"); setTimeout(() => setToast(""), 1600); };
  const signIn = async () => { await authService.signIn(); update({ authenticated: true }); go("home"); };
  const signOut = async () => { await authService.signOut(); update({ authenticated: false, isOnline: false }); go("login"); };
  if (loading) return <View style={[s.root, { alignItems: "center", justifyContent: "center" }]}><ActivityIndicator color="#0B63CE" size="large" /><Text style={[s.muted, { marginTop: 12 }]}>Preparing your worker workspace…</Text></View>;
  let content: React.ReactNode = null;
  if (screen === "welcome") content = <Welcome go={go} />;
  if (screen === "login") content = <Login go={go} signIn={signIn} />;
  if (screen === "register") content = <Register go={go} onRegistered={() => { update({ authenticated: true }); go("details"); }} />;
  if (screen === "details") content = <WorkerDetails go={go} state={state} update={update} />;
  if (screen === "area") content = <ServiceArea go={go} state={state} update={update} />;
  if (screen === "success") content = <SetupSuccess go={go} state={state} />;
  if (screen === "ready") content = <Ready go={go} update={update} />;
  if (screen === "home") content = <Home go={go} state={state} update={update} />;
  if (screen === "jobs") content = <Jobs go={go} state={state} update={update} />;
  if (screen === "job") content = <JobDetails go={go} state={state} update={update} />;
  if (screen === "accepted") content = <Accepted go={go} state={state} />;
  if (screen === "navigation") content = <Navigation go={go} state={state} />;
  if (screen === "arrived") content = <Arrived go={go} state={state} />;
  if (screen === "start") content = <StartWork go={go} state={state} />;
  if (screen === "work") content = <Work go={go} state={state} update={update} />;
  if (screen === "materials") content = <Materials go={go} state={state} update={update} />;
  if (screen === "progress") content = <ProgressScreen go={go} state={state} update={update} />;
  if (screen === "photos") content = <Photos go={go} />;
  if (screen === "confirmation") content = <Confirmation go={go} state={state} update={update} />;
  if (screen === "completed") content = <Completed go={go} state={state} />;
  if (screen === "history") content = <History go={go} />;
  if (screen === "earnings") content = <Earnings go={go} />;
  if (screen === "notifications") content = <Notifications go={go} state={state} update={update} />;
  if (screen === "profile") content = <Profile go={go} state={state} />;
  if (screen === "settings") content = <Settings go={go} signOut={signOut} />;
  if (screen === "support") content = <Support go={go} />;
  return <AppShell screen={screen} go={go} state={state} update={update} signOut={signOut}>{content}{toast ? <View style={s.toast}><Text style={s.toastText}>{toast}</Text></View> : null}</AppShell>;
}
